// Type: Executor.
#[derive(Clone, Debug, PartialEq, Eq, Hash)]
pub enum Executor {
    Charter(ExecutorCharter),
    Procedure(ExecutorProcedure),
    Role(ExecutorRole),
    Job(ExecutorJob),
}

// Record: Executor.
impl Record for Executor {
    type Limits = Limits;
    const TAIL: Path = paths::EXECUTOR_TAG;

    fn encoded_bound(limits: &Limits) -> Option<u64> {
        Some(skein_codec::bounds::declaration(TABLE, limits.values().as_slice(), CEILING_VALUES, 247)?.encoded)
    }

    fn decoded_bound(limits: &Limits) -> Option<u64> {
        Some(skein_codec::bounds::declaration(TABLE, limits.values().as_slice(), CEILING_VALUES, 247)?.decoded)
    }

    fn write(&self, limits: &Limits, out: &mut skein_lib::Writer) -> Result<(), Problem> {
        match self {
            Self::Charter(value) => { field::put(out, &[0], paths::EXECUTOR_TAG)?; value.write(limits, out) },
            Self::Procedure(value) => { field::put(out, &[1], paths::EXECUTOR_TAG)?; value.write(limits, out) },
            Self::Role(value) => { field::put(out, &[2], paths::EXECUTOR_TAG)?; value.write(limits, out) },
            Self::Job(value) => { field::put(out, &[3], paths::EXECUTOR_TAG)?; value.write(limits, out) },
        }
    }

    fn read(limits: &Limits, reader: &mut skein_lib::Reader<'_>) -> Result<Self, Problem> {
        let tag = reader.u8().ok_or(Problem { path: paths::EXECUTOR_TAG, reason: skein_codec::Reason::Short })?;
        match tag {
            0 => Ok(Self::Charter(ExecutorCharter::read(limits, reader)?)),
            1 => Ok(Self::Procedure(ExecutorProcedure::read(limits, reader)?)),
            2 => Ok(Self::Role(ExecutorRole::read(limits, reader)?)),
            3 => Ok(Self::Job(ExecutorJob::read(limits, reader)?)),
            4..=u8::MAX => Err(Problem { path: paths::EXECUTOR_TAG, reason: skein_codec::Reason::Tag }),
        }
    }
}

